    knurl(c, root, 'scope_focus_grip_', [fx, y, 0], d.eye + .001, L * .057, 'x', 18, 'rubber');
    torus(c, root, 'scope_focus_accent', d.eye + .001, .0015, [fx + L * .034, y, 0], accent);
    const tx = -L * .015;
