 if(B.def?.number>0){const seat=p(0,-1.25),room=B.rooms.find(r=>x>=r.x0&&x<=r.x1&&z>=r.z0&&z<=r.z1);B.officeSeats.push({id:B.id+'-desk-'+B.officeSeats.length,x:seat.x,z:seat.z,h:0,roomId:room?.id||'hub',desk:{x,z,h:.85},yaw,seatHeight:.565,deskHeight:.85,workOffset:.3,handForward:.7,stands:[p(-.95,-1.25),p(.95,-1.25),p(0,-2.25)]});}
