    for(const r of [[a.x0,x0,a.z0,a.z1],[x1,a.x1,a.z0,a.z1],[x0,x1,a.z0,z0],[x0,x1,z1,a.z1]])if(r[1]-r[0]>.015&&r[3]-r[2]>.015)B.box(deck,(r[0]+r[1])/2,-.16,(r[2]+r[3])/2,r[1]-r[0]-.01,.32,r[3]-r[2]-.01);
