 for(const c of B.tiles.values())if(c.room==='corridor'&&(c.i+c.j)%3===0){B.box(steel,c.x,H-.15,c.z,1.8,.2,.22);B.box(coolLight,c.x,H-.27,c.z,1.55,.05,.11);}
