 const concreteTex=canvasTexture('facility-concrete',(c,w,h)=>{c.fillStyle='#b8c2c2';c.fillRect(0,0,w,h);let n=71861;for(let i=0;i<7000;i++){n=(Math.imul(n,1664525)+1013904223)>>>0;const x=n%w;n=(Math.imul(n,1664525)+1013904223)>>>0;const y=n%h;c.fillStyle=i%3?'#263e4412':'#ffffff35';c.fillRect(x,y,i%4+1,1);}c.strokeStyle='#263e4450';c.lineWidth=2;c.strokeRect(1,1,w-2,h-2);c.strokeStyle='#ffffff38';c.lineWidth=1;c.strokeRect(4,4,w-8,h-8);for(const [x,y]of[[14,14],[w-14,14],[14,h-14],[w-14,h-14]]){c.fillStyle='#45575b';c.fillRect(x,y,3,3);}},512,512);
 const steelTex=canvasTexture('facility-steel',(c,w,h)=>{c.fillStyle='#81979e';c.fillRect(0,0,w,h);for(let y=0;y<h;y+=16)for(let x=0;x<w;x+=24){c.strokeStyle='#d4ddde66';c.lineWidth=2;c.beginPath();c.moveTo(x+(y%32?12:0),y+4);c.lineTo(x+8+(y%32?12:0),y+10);c.stroke();}c.fillStyle='#243e4430';for(let y=0;y<h;y+=4)c.fillRect(0,y,w,1);},256,256);
 let groundTex=texCache.get('facility-ground-repeat');if(!groundTex){groundTex=concreteTex.clone();groundTex.wrapS=groundTex.wrapT=T.RepeatWrapping;groundTex.repeat.set(52.5,40);groundTex.needsUpdate=true;texCache.set('facility-ground-repeat',groundTex);}
 const ground=material('facility-floor',0x697c82,{map:groundTex,roughness:.88}),wall=material('facility-concrete',0x85969a,{map:concreteTex,roughness:.91}),roof=material('facility-roof',0x465b65,{roughness:.91});
 const dark=material('facility-dark',0x172a35,{map:steelTex,metalness:.62,roughness:.54}),deckMat=material('facility-deck',0x72858c,{map:steelTex,metalness:.64,roughness:.57}),white=material('facility-ceramic',0xc7d5d5,{metalness:.12,roughness:.50}),orange=material('facility-warning',0xe5b35d,{roughness:.58});
 const cyan=material('facility-cyan',0xa5fff0,{emissive:0x5bdfdb,emissiveIntensity:1.6,roughness:.35}),light=material('facility-strip',0xe1f0ed,{emissive:0xbbdedb,emissiveIntensity:1.35}),red=material('facility-red',0xda6f61,{emissive:0x6a211c,emissiveIntensity:.45});
 const windowMat=material('facility-glass',0x81b9c6,{transparent:true,opacity:.20,metalness:.12,roughness:.12,depthWrite:false,side:T.DoubleSide});
 const screenTex=canvasTexture('facility-diagram',(c,w,h)=>{c.fillStyle='#0b222d';c.fillRect(0,0,w,h);c.strokeStyle='#365965';c.lineWidth=1;for(let x=0;x<w;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}c.strokeStyle='#87dfcb';c.lineWidth=3;c.strokeRect(80,85,430,280);for(let i=0;i<4;i++){c.strokeRect(110+i*96,120,65,82);c.strokeRect(110+i*96,250,65,82);}c.beginPath();c.arc(296,225,70,0,TAU);c.stroke();c.fillStyle='#a7dbd1';c.font='24px monospace';c.fillText('PENTA / SYSTEM OVERVIEW',50,46);c.font='15px monospace';c.fillText('SECTOR 05     INTERNAL NETWORK',50,427);for(let j=0;j<7;j++){c.fillStyle=j===5?'#dfad66':'#5caeae';c.fillRect(570,96+j*42,100+(j*47)%200,9);c.fillStyle='#c2d6d5';c.fillRect(570,111+j*42,50+(j*29)%130,3);}c.strokeStyle='#dfad66';c.beginPath();for(let i=0;i<34;i++){const x=570+i*8,y=421-Math.sin(i*.6)*12-(i%7)*3;i?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();},960,480);
 const diagram=material('facility-monitor',0xffffff,{map:screenTex,emissiveMap:screenTex,emissive:0x8bbbbb,emissiveIntensity:.65,roughness:.42});
 // A small set of reusable geometries, instanced by material.
 const shapes=new Map(),instances=new Map(),Y=new T.Vector3(0,1,0);
 function batch(shape,mat,x,y,z,sx,sy,sz,q=identityQ){const k=shape+'|'+mat.name;let b=instances.get(k);if(!b){let geo=shapes.get(shape);if(!geo){geo=shape==='cyl24'?new T.CylinderGeometry(1,1,1,24):shape==='cyl12'?new T.CylinderGeometry(1,1,1,12):shape==='ring'?new T.TorusGeometry(1,.025,6,48):shape==='leaf'?new T.IcosahedronGeometry(1,1):shape==='dome'?new T.SphereGeometry(1,24,12,0,TAU,0,Math.PI/2):new T.CylinderGeometry(1,1,1,8);shapes.set(shape,geo);B.resources.push(geo);}b={geo,mat,matrices:[]};instances.set(k,b);}b.matrices.push(new T.Matrix4().compose(new T.Vector3(x,y,z),q,new T.Vector3(sx,sy,sz)));B.props++;}
 function cyl(mat,x,y,z,r,h,sides=12,q=identityQ){batch(sides===24?'cyl24':'cyl12',mat,x,y,z,r,h,r,q);}
 function rod(mat,a,b,r=.09){const p=new T.Vector3(...a),v=new T.Vector3(...b).sub(p),len=v.length();if(len<.001)return;const q=new T.Quaternion().setFromUnitVectors(Y,v.clone().normalize());p.addScaledVector(v,.5);batch('cyl8',mat,p.x,p.y,p.z,r,len,r,q);}
 function beam(mat,a,b,w=.3,d=w){const p=new T.Vector3(...a),v=new T.Vector3(...b).sub(p),q=new T.Quaternion().setFromUnitVectors(Y,v.clone().normalize());p.addScaledVector(v,.5);const arr=B.batches.get(mat)||[];arr.push(new T.Matrix4().compose(p,q,new T.Vector3(w,v.length(),d)));B.batches.set(mat,arr);B.props++;}
