          // Optimized GLBs interleave normalized normals in padded strides.
          // BufferGeometryUtils merging requires standalone attributes.
          for (const [name, attribute] of Object.entries(geometry.attributes)) if (attribute.isInterleavedBufferAttribute) {
            const source = attribute.data.array, array = new source.constructor(attribute.count * attribute.itemSize);
            for (let i = 0; i < attribute.count; i++) for (let j = 0; j < attribute.itemSize; j++) array[i * attribute.itemSize + j] = source[i * attribute.data.stride + attribute.offset + j];
            geometry.setAttribute(name, new T.BufferAttribute(array, attribute.itemSize, attribute.normalized));
          }
