        c.fillStyle='#f8fafc';c.strokeStyle='#183746';c.lineWidth=1.5;c.beginPath();c.arc(x,y,labels?4:3,0,TAU);c.fill();c.stroke();
        if(labels){c.font='800 10px system-ui';c.lineWidth=3;c.strokeStyle='#122332';c.strokeText(st.name,x,y+(st.index%2?-14:14));c.fillStyle='#fff2ca';c.fillText(st.name,x,y+(st.index%2?-14:14));}
