      const q=pentaToLocal(e.x,e.y),falling=!!e.pentaFalling,feet=falling?baseOf(e):null,f=pentaFloorOf(e),rad=PENTA_RADIUS;
      if(!falling&&f>=0&&e.pentaFloor!==f)pentaSetFloor(e,f);
