          let candidate = layout.cells.find(c => c.id === cell);
          if (!candidate || candidate.stair || used.has(cell)) candidate = layout.cells.find(c => !c.stair && !used.has(c.id) && c.r >= 1 && !c.furnished);
          cell = candidate.id; used.add(cell);
          const home = pentaCellPoint(floor, cell), adjacent = layout.adjacency[cell].filter(id => !layout.stairCells.some(sc => sc.id === id));
          const next = adjacent[i % Math.max(1, adjacent.length)] || cell;
