          const role = floor === 4 && i === 0 ? 'commander' : (floor >= 3 && i % 3 !== 2) || i % 5 === 0 ? 'elite' : i % 4 === 2 ? 'breacher' : 'rifle';
          add(floor, role, cell, home, role === 'commander' ? [home] : [home, pentaCellPoint(floor, next), pentaCellPoint(floor, third)]);
