      el.id='hanq-penta-transition';
      el.style.cssText='position:absolute;inset:0;background:#070d13;color:#e5ece9;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;z-index:99;opacity:0;pointer-events:none;font:600 13px system-ui;letter-spacing:.1em;';
      const txt=document.createElement('div');txt.style.cssText='text-align:center;max-width:80%;text-shadow:0 1px 8px #000;';el.appendChild(txt);
