      p.x=pos.x;p.y=pos.y;p.piHeight=q.h||0;p.floor=piFloorY(to)+p.piHeight-G(p.x,p.y);
      p.indoorPenta=true;p.indoorFloor=to;p.piLast={x:p.x,y:p.y,h:p.piHeight};
      p.jz=p.vz=0;p.vx=p.vy=0;p.alt=0;p.air=false;p.plat=null;p.climb=null;
