    // PENTA_COMBAT_START — local traces use absolute world altitude, including B1 and roof.
    // These helpers only query PENTA geometry. The original terrain/obstacle tests still run.
    function pentaTraceNear(x1,y1,x2,y2) {
      if(!pentaWorld)return false;
      let lo=0,hi=1;
      const traceBounds=piTraceBounds(),span=traceBounds.span;
      const axes=[[x1,x2-x1,pentaWorld.x-span,pentaWorld.x+span],[y1,y2-y1,pentaWorld.y-span,pentaWorld.y+span]];
      for(const a of axes){
        if(Math.abs(a[1])<1e-10){if(a[0]<a[2]||a[0]>a[3])return false;continue;}
        let u=(a[2]-a[0])/a[1],v=(a[3]-a[0])/a[1];if(u>v){const t=u;u=v;v=t;}
        lo=Math.max(lo,u);hi=Math.min(hi,v);if(lo>hi)return false;
      }
      return true;
    }
    function pentaTraceHit(x1,h1,y1,x2,h2,y2) {
      if(!pentaWorld)return null;
      const dx=x2-x1,dy=y2-y1,dh=h2-h1;
      let lo=0,hi=1;
      // Clip both horizontal extent and height before taking any samples. A 2km ray
      // costs only the portion inside this small compound, and overhead rays cost zero.
      const traceBounds=piTraceBounds(),span=traceBounds.span;
      const axes=[[x1,dx,pentaWorld.x-span,pentaWorld.x+span],[y1,dy,pentaWorld.y-span,pentaWorld.y+span],[h1,dh,traceBounds.low,traceBounds.high]];
      for(const a of axes){
        if(Math.abs(a[1])<1e-10){if(a[0]<a[2]||a[0]>a[3])return null;continue;}
        let u=(a[2]-a[0])/a[1],v=(a[3]-a[0])/a[1];if(u>v){const t=u;u=v;v=t;}
        lo=Math.max(lo,u);hi=Math.min(hi,v);if(lo>hi)return null;
      }
      const length=Math.hypot(dx,dy,dh),steps=Math.max(1,Math.ceil(length*(hi-lo)/.10));
      let previous=lo;
      for(let i=0;i<=steps;i++){
        const u=lo+(hi-lo)*i/steps,x=x1+dx*u,y=y1+dy*u,h=h1+dh*u,block=pentaSolidAt(x,y,h);
        if(block){
          let a=previous,b=u;
          // Retain the last free point as well as the contact point for muzzle clamping.
          for(let j=0;j<7&&b>a;j++){
            const m=(a+b)/2;if(pentaSolidAt(x1+dx*m,y1+dy*m,h1+dh*m))b=m;else a=m;
          }
          return {x:x1+dx*b,y:y1+dy*b,h:h1+dh*b,u:b,t:length*b,block,
            px:x1+dx*a,py:y1+dy*a,ph:h1+dh*a};
        }
        previous=u;
      }
      return null;
    }
    function pentaTraceBlocked(x1,h1,y1,x2,h2,y2) {
      return !!pentaTraceHit(x1,h1,y1,x2,h2,y2);
    }
    // Call after applying a grenade substep and before the generic nadeBlock branch.
    // Return true to skip generic surfaceTop handling for this substep. The latter
    // interprets hgt as absolute altitude, which is incorrect for PENTA's local walls.
    function pentaNadeCollision(g,ox,oy,oh) {
      const hit=pentaTraceHit(ox,oh,oy,g.x,g.h,g.y);if(!hit)return false;
      const probe=.025,occupied=(x,y,h)=>pentaSolidAt(x,y,h)?1:0;
      let nx=occupied(hit.x-probe,hit.y,hit.h)-occupied(hit.x+probe,hit.y,hit.h);
      let ny=occupied(hit.x,hit.y-probe,hit.h)-occupied(hit.x,hit.y+probe,hit.h);
      let nh=occupied(hit.x,hit.y,hit.h-probe)-occupied(hit.x,hit.y,hit.h+probe);
      let n=Math.hypot(nx,ny,nh);
      if(n<1e-8){
        // A thrown grenade may initially overlap a thin wall by its .4m hand offset.
        // Back out toward the thrower rather than mistaking a wall for a ground plane.
        if(hit.block.kind==='pentaWall'){
          nx=ox-g.x;ny=oy-g.y;nh=0;
          if(Math.hypot(nx,ny)<1e-8&&g.owner){nx=g.owner.x-hit.x;ny=g.owner.y-hit.y;}
          if(Math.hypot(nx,ny)<1e-8){nx=-g.vx;ny=-g.vy;}
          if(Math.hypot(nx,ny)<1e-8)nx=1;
        }else{nx=0;ny=0;nh=g.h<oh||g.vh<=0?1:-1;}
        n=Math.hypot(nx,ny,nh);
      }
      nx/=n;ny/=n;nh/=n;
      let x=hit.x+nx*.08,y=hit.y+ny*.08,h=hit.h+nh*.08;
      // Clear the collision shell. The bound is smaller than a doorway; it cannot
      // move a grenade to another floor or through an unrelated room.
      for(let i=0;i<10&&pentaSolidAt(x,y,h);i++){x+=nx*.04;y+=ny*.04;h+=nh*.04;}
      if(pentaSolidAt(x,y,h)&&!pentaSolidAt(ox,oy,oh)){x=ox;y=oy;h=oh;}
      g.x=x;g.y=y;g.h=h;
      const vn=g.vx*nx+g.vy*ny+g.vh*nh;
      if(vn<0){
        const horizontal=Math.abs(nh)<.5;
        const restitution=horizontal?.45:(-vn*.3<.6?0:.3);
        g.vx-=(1+restitution)*vn*nx;
        g.vy-=(1+restitution)*vn*ny;
        g.vh-=(1+restitution)*vn*nh;
        if(nh>.5){g.vx*=.6;g.vy*=.6;}
      }
      return true;
    }
    // PENTA_COMBAT_END

    // PENTA rendering adapter: embedded inside the existing game's create(api).
