      const previous=three.penta;
      if(previous?.world===s.world) { previous.root.removeFromParent(); parentGroup.add(previous.root);pentaSurfaceRebind(); return previous; }
      if(previous){pentaSurfaceUnbind();previous.root.removeFromParent();}
