      root.name='PENTA_Secure_Compound';root.position.set(w.x,w.baseY,w.y);root.rotation.y=w.rotation||0;
      root.userData={penta:true,asset:'PENTA / 05',baseY:w.baseY};root.add(model.root);parentGroup.add(root);
      const security=new T.Group();security.name='PENTA_Perimeter_Security';root.add(security);
      const material=(name,color,extra={})=>{const m=new T.MeshStandardMaterial({color,roughness:.78,...extra});m.name=name;return m;};
      const mats={concrete:material('PENTA security concrete',0x868e8e),dark:material('PENTA security steel',0x243334,{metalness:.45}),white:material('PENTA security markings',0xdcd9ca),glass:material('PENTA gatehouse dark glass',0x28414b,{metalness:.22,roughness:.2}),yellow:material('PENTA warning amber',0xd5a745),red:material('PENTA alarm beacon',0xbe332b,{emissive:0xf03016,emissiveIntensity:.5}),green:material('PENTA active console',0x42bdaa,{emissive:0x36b49f,emissiveIntensity:.5})};
