      const plaza=own(new T.Mesh(plazaGeometry,mats.concrete));plaza.name='PENTA_Excavation_Plaza';root.add(plaza);
      const normal=A.ENTRY.outward,tangent={x:normal.z,z:-normal.x},gateAngle=Math.atan2(normal.x,normal.z);
      const gatePoint=(side,out)=>({x:normal.x*out+tangent.x*side,z:normal.z*out+tangent.z*side});
      let perimeter=typeof pentaPerimeter==='function'?pentaPerimeter():null;
      if(!Array.isArray(perimeter)||!perimeter.length){
        perimeter=[];const a0=Math.atan2(normal.z,normal.x),gap=Math.asin(7/84);
        for(let i=0;i<36;i++){const a=a0+gap+(Math.PI*2-2*gap)*i/36,b=a0+gap+(Math.PI*2-2*gap)*(i+1)/36;perimeter.push({a:{x:84*Math.cos(a),z:84*Math.sin(a)},b:{x:84*Math.cos(b),z:84*Math.sin(b)}});}
      }
