        surfaceId='penta:perimeter:'+edgeIndex;
        const dx=edge.b.x-edge.a.x,dz=edge.b.z-edge.a.z,L=Math.hypot(dx,dz),angle=-Math.atan2(dz,dx),mx=(edge.a.x+edge.b.x)/2,mz=(edge.a.z+edge.b.z)/2;
