        for(let i=1;i<way.length;i++)F.access.push({x1:way[i-1].x,y1:way[i-1].y,x2:way[i].x,y2:way[i].y,penta:true,primary:true});
        const site={id:s.world.sites.length,type:'penta',x:F.x,y:F.y,r:115,name:'PENTA V · 최고 보안 미궁',region:'mountain',fixed:true};
