    function dwRender(dt,camera){
      if(!three||!s?.deepworks||!pentaWorld)return;
      const T=THREE,p=s.ents[0],f=p.deepFloor,active=!!DW_SPECS[f];
      dwLegacySurfaceRender(active);
      if(three.staticGroup)three.staticGroup.visible=!active;
      if(three.water)three.water.visible=!active;
      if(three.open?.root)three.open.root.visible=!active;
      if(three.penta?.root)three.penta.root.visible=!active&&three.penta.root.visible;
      if(three.dwSceneWorld!==s.world){
        if(three.dwGroup){
          const old=three.dwGroup;old.removeFromParent();old.traverse(o=>{if(o.isMesh){o.geometry.dispose();if(o.material?.dispose)o.material.dispose();}});
        }
        three.dwSceneWorld=s.world;three.dwGroup=new T.Group();three.dwGroup.name='DEEPWORKS_Subterranean';three.scene.add(three.dwGroup);three.dwFloors={};
      }
      const level=f&&DW_SPECS[f]?dwLayout(f):null;
      if(active&&!three.dwFloors[f]){
        const group=new T.Group();group.name='DEEPWORKS_B'+f;three.dwGroup.add(group);
        const deck=new T.MeshStandardMaterial({color:f===2?0x616c70:f===3?0x536b71:0x3e4c5b,roughness:.85,side:T.DoubleSide});
        const steel=new T.MeshStandardMaterial({color:0x26333d,metalness:.42,roughness:.65,side:T.DoubleSide});
        const light=new T.MeshStandardMaterial({color:f===4?0xdf7a6b:0x6ec4c4,emissive:f===4?0x853122:0x23696e,emissiveIntensity:1.3});
        const warning=new T.MeshStandardMaterial({color:0xe5b34f,roughness:.7});
        const trapMat=new T.MeshStandardMaterial({color:0xab3f33,roughness:.55,emissive:0x541311,emissiveIntensity:.3});
        const cube=new T.BoxGeometry(1,1,1),bins=new Map();
        const add=(mat,x,y,z,w,h,d)=>{
          if(!bins.has(mat))bins.set(mat,[]);
          const matrix=new T.Matrix4().compose(new T.Vector3(x,y,z),new T.Quaternion(),new T.Vector3(w,h,d));
          bins.get(mat).push(matrix);
        };
        const y=dwHeight(f),R=level;
        add(deck,0,y-.26,0,R.w*24,.50,R.h*24);
        add(steel,0,y+R.height+.16,0,R.w*24,.28,R.h*24);
        for(const wall of R.walls)add(steel,wall.x,y+R.height/2,wall.z,wall.w,R.height,wall.d);
        for(let i=0;i<R.n;i++){
          const q=R.point(i);
          add(deck,q.x,y+.06,q.z,21.8,.08,21.8);
          if(i%3===0){
            add(light,q.x,y+R.height-.27,q.z,3,.10,.19);
            for(const z of[-8.7,8.7])add(warning,q.x,y+.05,q.z+z,2,.04,.1);
          }
          if(!R.hall.has(i)&&i%5===2){
            for(let j=0;j<3;j++)add(steel,q.x-5+j*3.3,y+.63,q.z+8,2.9,1.1,1.65);
          }
        }
        for(const h of R.hazards){
          add(trapMat,h.x,y+.14,h.z,4,.27,4);
          for(const side of[-1,1])add(light,h.x+side*1.75,y+.48,h.z,.15,.63,2.85);
        }
        for(const [mat,mats]of bins){
          const mesh=new T.InstancedMesh(cube,mat,mats.length);mesh.name='B'+f+'_'+mat.name;
          mats.forEach((m,i)=>mesh.setMatrixAt(i,m));mesh.instanceMatrix.needsUpdate=true;group.add(mesh);
        }
        const waypoint=R.point(0),target=R.point(R.n-1);
        for(const [q,color]of[[waypoint,light],[target,warning]]){
          const marker=new T.Mesh(new T.CylinderGeometry(1.4,1.4,.1,12),color);
          marker.position.set(q.x,y+.1,q.z);group.add(marker);
        }
        group.position.set(pentaWorld.x,0,pentaWorld.y);group.rotation.y=pentaWorld.rotation;
        three.dwFloors[f]=group;
      }
      for(const [key,obj]of Object.entries(three.dwFloors||{}))obj.visible=active&&Number(key)===f;
      three.dwGroup.visible=active;
    }
    function dwHUD(c,w){
      if(!s?.deepworks)return;
      const p=s.ents[0],f=p.deepFloor;
      if(!DW_SPECS[f]){
        if(s.layout){delete s.layout.dwUp;delete s.layout.dwDown;delete s.layout.dwDisarm;}
        return;
      }
      const L=s.layout||{};delete L.dwDown;delete L.dwDisarm;
      const startX=Math.max(9,(w-320)/2),y=180;
      panel(c,startX,y,Math.min(320,w-18),60,8,.86);
      c.save();c.fillStyle='#8af7e4';c.font='900 12px system-ui';c.textAlign='left';
      const remaining=s.deepworks.units.filter(u=>u.f===f&&!u.dead).length;
      c.fillText('DEEPWORKS B'+f+'  |  보안 '+remaining+'명',startX+10,y+19);
      c.font='700 10px system-ui';c.fillStyle='#e2e8f0';
      const hazard=dwTrapNear(),portal=dwPortal();
      c.fillText(hazard?'함정 접근 · E 키로 해제':portal?'승강기 · E 키로 이동':'경계 미궁 · 붉은 함정을 주의하세요',startX+10,y+39);
      if(hazard)L.dwDisarm={x:startX+120,y:y+55,r:20};
      if(portal)L.dwDown={x:startX+265,y:y+55,r:20};
      c.restore();
    }
