    // DEEPWORKS-POST-RESTORE START
    function dwAfterRestore(){
      if(s?.mode!=='open')return;
      pentaWorld=s.world?.penta||null;
      if(!pentaWorld||!s.deepworks||!s.open.penta)dwInstall();
      pentaWorld=s.world.penta;
      const F=s.world.penta;
      if(F?.site&&!s.world.sites.includes(F.site))s.world.sites.push(F.site);
      if(F?.site&&!s.open.sites.includes(F.site))s.open.sites=s.world.sites;
      const D=s.deepworks;
      if(D?.units)for(const u of D.units){
        if(u.entity&&!u.entity.alive)u.dead=true;
        if(u.entity?.alive&&!s.ents.includes(u.entity))s.ents.push(u.entity);
      }
      if(D){
        const kinds=['tank','helicopter','mlrs'],missing=kinds.filter(kind=>!s.vehicles.some(v=>v.dwId==='deepworks:ally:'+kind));
        if(missing.length){
          D.vehicleIds=(D.vehicleIds||[]).filter(id=>!missing.some(k=>id==='deepworks:ally:'+k));
          dwPlaceVehicles();
        }
      }
      if(s.open)s.open.fogDirty=true;
      s.mapDirty=true;
    }
    function dwCanInteract(){return !!(dwTrapNear()||dwPortal());}
    function dwLegacySurfaceRender(active){
      if(!three||!s?.world?.penta?.legacyPlatform)return;
      if(three.dwIslandWorld!==s.world){
        if(three.dwIsland){three.dwIsland.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose();}});three.dwIsland.removeFromParent();}
        const T=THREE,F=s.world.penta,g=new T.Group();g.name='PENTA_Legacy_Island_And_Bridge';three.scene.add(g);
        const deck=new T.MeshStandardMaterial({color:0x76878b,roughness:.88,metalness:.12,side:T.DoubleSide});
        const edge=new T.MeshStandardMaterial({color:0x38484e,roughness:.80});
        const ring=(r1,r2,y,thick)=>{
          const vertices=r=>Array.from({length:5},(_,i)=>{const a=-Math.PI/2+i*Math.PI*2/5;return new T.Vector2(Math.cos(a)*r,Math.sin(a)*r);});
          const s=new T.Shape(vertices(r2));s.holes.push(new T.Path(vertices(r1).reverse()));
          const geo=new T.ExtrudeGeometry(s,{depth:thick,bevelEnabled:false});
          geo.rotateX(-Math.PI/2);geo.translate(F.x,y,F.y);
          const m=new T.Mesh(geo,deck);g.add(m);
        };
        ring(47.5,112,F.baseY-.65,.24);
        const way=[{x:1460,y:760},{x:1584,y:640},{x:1696,y:456},F.approach];
        for(let i=1;i<way.length;i++){
          const a=way[i-1],b=way[i],L=Math.hypot(b.x-a.x,b.y-a.y),mid=(a,b)=>(a+b)/2;
          const y=F.baseY-.49;
          const m=new T.Mesh(new T.BoxGeometry(L,.35,13),deck);
          m.position.set(mid(a.x,b.x),y,mid(a.y,b.y));m.rotation.y=-Math.atan2(b.y-a.y,b.x-a.x);g.add(m);
          for(const side of[-1,1]){const p=new T.Mesh(new T.BoxGeometry(L,.65,.16),edge);
            p.position.set(mid(a.x,b.x)-Math.sin(m.rotation.y)*side*6.7,y+.25,mid(a.y,b.y)+Math.cos(m.rotation.y)*side*6.7);p.rotation.y=m.rotation.y;g.add(p);}
        }
        three.dwIsland=g;three.dwIslandWorld=s.world;
      }
      three.dwIsland.visible=!active;
    }
