    function cellAt(x, y) {
      const w = s.world;
      return w.grid[Math.min(w.GN - 1, Math.max(0, Math.floor(y / w.CELL))) * w.GN + Math.min(w.GN - 1, Math.max(0, Math.floor(x / w.CELL)))];
    }
    // blocks ground-level movement (ignores lintels, roofs and tower platforms overhead)
    const WATER = { kind: 'water' };
    function pointBlocked(x, y) {
      if(nfGround(x,y)!==undefined)return null;
      const hh=hkBlocked(x,y);if(hh!==undefined)return hh;
      if(railLive()){const h=G(x,y)+.8;if(railStaticAt(x,y,h)||railCarAt(x,y,h,R))return RAIL_SOLID;}
      if(piCurrent()&&piInRange(x,y))return piPassableWorld(s.ents[0],x,y)?null:PI_WALL;
      const pw=pentaPointBlocked(x,y);if(pw)return pw;
      if(ncRuntime&&!ncNativeQuery){const hit=ncRuntime.pointBlocked(x,y,s.ents[0]);if(hit!==undefined)return hit;}
      const eb=efPoint(x,y);if(eb!==undefined)return eb;
      const wb = wptPointBlocked(x, y); if (wb !== undefined) return wb;
      if (x < 0 || y < 0 || x > MAP || y > MAP) return G_OUT ? WATER : null;
      if (G_OUT && G(x, y) < -0.4) return WATER;
      const cell = cellAt(x, y);
      for (const r of cell.rects) if (!r.dead && !(r.hmin > 1.2) && x > r.x && x < r.x + r.w && y > r.y && y < r.y + r.h && battleSurfaceBodySolid(r,x,y,(r.gy||r.parent?.gy||0)+.08,(r.gy||r.parent?.gy||0)+BODY_H,0.001)) return r;
      // Replay the original seeded placement decisions; expanded bark applies
      // to live collision after indexing, so saved object identities stay fixed.
      for (const c of cell.circles) if (!generatingWorld&&c.kind==='tree'&&!c.pine?nativeBarkContact(c,x,y,G(x,y)+.06,G(x,y)+BODY_H,0):(x-c.x)**2+(y-c.y)**2<c.r*c.r) return c;
      return null;
    }
