      const steer=controlled?clamp((k.has('d')||k.has('arrowright')?1:0)-(k.has('a')||k.has('arrowleft')?1:0)+(m?.active?m.dx:0),-1,1):0;
      const ascent=controlled?clamp((k.has('space')||k.has(' ')?1:0)-(k.has('shift')?1:0)+(s.input.heli?s.input.heli.dir:0),-1,1):0;
