        const r = aimRay(spreadBase);
        const startT = Math.max(0, (p.x - cam.x) * r.dx + (p.y - cam.z) * r.dz) - 0.2;
        let hit = rayCast(cam.x + r.dx * startT, cam.y + r.dy * startT, cam.z + r.dz * startT, r.dx, r.dy, r.dz, w.range * 1.2, p);
        // the gun itself must see the hit point (no shooting through a wall you hug)
        const gd = Math.hypot(hit.x - m.x, hit.y - m.y);
        const n = Math.ceil(gd / (pentaTraceNear(m.x,m.y,hit.x,hit.y)?.10:.4));
        for (let k = 1; k < n; k++) {
          const x = m.x + ((hit.x - m.x) * k) / n, y = m.y + ((hit.y - m.y) * k) / n, h = m.h + ((hit.h - m.h) * k) / n;
          const b = solidAt(x, y, h);
          if (b) { hit = b === TERRAIN ? { x, h, y, ground: true } : { x, h, y, block: b }; break; }
        }
