        if(i===0)battleAudioImpact(hit);
        addTracer(m.x, m.h, m.y, hit.x, hit.h, hit.y, slot.type === 'sniper' ? 0.14 : 0.07);
        const falloff = dist > w.range ? 0.5 : 1;
        battleSurfaceMark(hit,m,slot.type,true);
        const cityHit = wptCommitShot(m, hit, w.dmg * falloff * (hit.head ? 1.8 : 1));
        if (cityHit?.hit) { hits++; head = head || !!hit.head; kill = kill || cityHit.killed; }
        else if(hit.nfShip){const result=nfDamage(hit.nfShip.id,w.dmg*falloff,'ally',slot.type,hit);if(result?.hit){hits++;kill=kill||result.killed;}}
