          addParts(hit.x, hit.h, hit.y, hit.block && (hit.block.kind === 'tree' || hit.block.kind === 'crate') ? '#8b5a2b' : hit.ground ? '#b7a77a' : '#e5e7eb', 5, 2.2, 0.35);
