        const responseId=meta?.block?.responseVehicleId;
        const response=responseId&&wpt?.rt?.sim.responseVehicles.find(v=>v.id===responseId);
        if(response){kind='vehicle';targetId='westport:response-vehicle:'+response.id;meta={...meta,westportHit:{kind:'response-vehicle',id:response.id,vehicle:response}};}
