      let v=responseBoardingViews.get(a);
      if(!v){v={id:'response-view:'+a.id,capturedResponseVehicle:a.id,driver:null,dead:false};responseBoardingViews.set(a,v);responseBoardingSources.set(v,a);}
      Object.assign(v,{x:a.x,y:a.z,gy:a.y,heading:Math.PI/2-a.heading,speed:a.speed||0,hp:a.hp,maxHp:a.maxHp});
