            const supported=ignore&&Number.isFinite(ignore.gy)&&h<=ignore.gy+.55;
            if(!supported&&h!==undefined&&bottom<h-.015&&top>h-surface.sy/Math.max(.1,Math.cos(surface.rz||0)))return WPT_TERRAIN;
