      s.input.look=s.input.fireTouch=s.input.drag=s.input.freeLookTouch=null;
      s.aimNade=null;s.pickPrompt=s.craftPrompt=s.ladderPrompt=null;s.vehPrompt=v;s.mapOpen=false;
      s.yaw=v.heading;s.pitch=.08;resetVehicleAim();s.mapDirty=true;
