        const w = (x < 0.18 * L ? 1 - 0.1 * smooth(-0.2 * L, -0.47 * L, x) : Math.pow(Math.max(0, Math.cos(((x - 0.18 * L) / (0.32 * L)) * (Math.PI / 2))), 0.75)) * B / 2;
