        // their own unattended timer, and occupied vehicles stay in use.
        if(!v||v.driver||s.ents[0].vehicle===v||Math.hypot(v.x-spec.x,v.y-spec.y)>45||v.ncAirborne||(v.altitude||0)>2)continue;
