          for (let k = -90; k <= 90; k += 18) { const m = new T.Mesh(t3.geo.box, paintW); m.scale.set(st.hor ? 8 : 0.8, 0.13, st.hor ? 0.8 : 8); m.position.set(st.x + (st.hor ? k : 0), gy + 0.03, st.y + (st.hor ? 0 : k)); m.userData.battleSurfaceFollower = strip; g.add(m); }
