      drawVehicleMarks(c, cx, cy, k, S, 0.85);
      for (const e of s.ents) if (!e.isPlayer && !e.efUnit && e.alive && e.ai && e.ai.target) { const x = (e.x - cx) * k, y = (e.y - cy) * k; c.fillStyle = '#ef4444'; c.beginPath(); c.arc(x, y, 2, 0, TAU); c.fill(); }
      for (const a of O.armor) if (!a.dead && a.alert > 0) { const x = (a.x - cx) * k, y = (a.y - cy) * k; c.fillStyle = '#f97316'; c.fillRect(x - 2.5, y - 2.5, 5, 5); }
