      c.fillStyle = '#facc15'; c.strokeStyle = '#000'; c.lineWidth = 1;
      c.beginPath(); c.moveTo(7, 0); c.lineTo(-5, -5); c.lineTo(-2, 0); c.lineTo(-5, 5); c.closePath(); c.fill(); c.stroke();
      c.restore();
      c.strokeStyle = 'rgba(255,255,255,0.7)'; c.lineWidth = 1.5; rr(c, x0, y0, S, S, 10); c.stroke();
      c.fillStyle = '#fff'; c.font = '900 10px system-ui'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText('N', x0 + S / 2, y0 + 9);
      const L = s.layout;
