        siteIcon(c, st, x, y, 1.15);
        c.lineWidth = 3; c.strokeStyle = 'rgba(0,0,0,0.65)'; c.strokeText(st.name, x, y + 13); c.fillStyle = st.hostile && !st.cleared ? '#fecaca' : '#fff'; c.fillText(st.name, x, y + 13);
