        ctx.fillText(failed ? '3D 엔진을 불러오지 못했어요' : '3D 월드 불러오는 중', w / 2, py + ph * 0.53);
        ctx.fillStyle = '#a5aea8'; ctx.font = `400 ${Math.min(13, pw / 29)}px system-ui`;
