      const piloting=v&&(v.kind==='plane'?p.craft===v&&v.pilot&&s.war?.me===v:p.vehicle===v&&v.driver===p);
      if(!p?.alive||!piloting||v.dead||v.hp<=0||api.state!=='playing'||s.mapOpen||p.railPassenger||s.pentaInterior?.transition||wpt?.rt?.isUiOpen)return;
      const aim=vehicleWeaponAim(v);if(!aim)return;
