    function touchBtn(c, b, kind, color, active, label) {
      if (!b) return;
      const g = c.createRadialGradient(b.x, b.y - b.r * 0.4, 2, b.x, b.y, b.r);
      g.addColorStop(0, active ? 'rgba(255,255,255,0.45)' : 'rgba(30,41,59,0.5)'); g.addColorStop(1, active ? 'rgba(255,255,255,0.25)' : 'rgba(2,6,23,0.45)');
      c.fillStyle = g; c.beginPath(); c.arc(b.x, b.y, b.r, 0, TAU); c.fill();
      c.strokeStyle = active ? 'rgba(253,224,71,0.9)' : 'rgba(255,255,255,0.5)'; c.lineWidth = 1.6; c.stroke();
      icon(c, kind, b.x, b.y - (label ? 4 : 0), b.r * 0.8, color);
      if (label) { c.fillStyle = 'rgba(255,255,255,0.88)'; c.font = '800 8.5px system-ui'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText(label, b.x, b.y + b.r * 0.56); }
    }
    function drawStick(c, h) {
      const mv = s.input.move;
      const on = mv && mv.active;
      const bx = on ? mv.bx : 112, by = on ? mv.by : h - 104;
      c.fillStyle = 'rgba(255,255,255,0.08)'; c.beginPath(); c.arc(bx, by, 54, 0, TAU); c.fill();
      c.strokeStyle = 'rgba(255,255,255,0.3)'; c.lineWidth = 2; c.stroke();
      const kx = on ? mv.dx * 54 : 0, ky = on ? mv.dy * 54 : 0;
      c.fillStyle = 'rgba(255,255,255,0.6)'; c.beginPath(); c.arc(bx + kx, by + ky, 21, 0, TAU); c.fill();
    }
    function drawAssassinTouch(c, w, h) {
      const p = s.ents[0], L = s.layout;
      const scoped = s.adsK > 0.5;
      const fx = w - 96, fy = h - 120;
      L.fire = { x: fx, y: fy, r: 42 };
      L.fire2 = { x: 68, y: h * 0.4, r: 28 };
      L.ads = { x: fx - 88, y: fy - 50, r: 27 };
      L.reload = { x: fx - 24, y: fy - 98, r: 24 };
      L.zoom = scoped ? { x: fx + 52, y: fy - 88, r: 23 } : null;
      L.crouch = { x: fx - 100, y: fy + 38, r: 23 };
      L.nade = null; L.heal = null; L.action = null;
      const holding = !!s.input.fireTouch;
      touchBtn(c, L.fire, holding && scoped ? 'breath' : 'fire', holding ? '#bfdbfe' : '#fff', holding, scoped ? (holding ? '떼면 발사' : '누르면 숨참기') : null);
      touchBtn(c, L.fire2, 'fire', '#fff', holding);
      touchBtn(c, L.ads, 'scope', s.input.adsToggle ? '#86efac' : '#fff', s.input.adsToggle, s.input.adsToggle ? '해제' : '스코프');
      touchBtn(c, L.reload, 'reload', '#fde68a', p.reloadT > 0);
      if (L.zoom) touchBtn(c, L.zoom, 'zoom', '#fff', false, `${s.zoomLvl}x`);
      touchBtn(c, L.crouch, 'crouch', p.crouch ? '#86efac' : '#fff', p.crouch, p.crouch ? '앉음' : '앉기');
      drawStick(c, h);
    }
    function drawMiniMarkers(c, cx, cy, k, S) {
      const M = s.mission;
      c.strokeStyle = 'rgba(253,224,71,0.85)'; c.lineWidth = 1.5; c.setLineDash([3, 3]);
      c.beginPath(); c.arc((M.town.x - cx) * k, (M.town.y - cy) * k, 36 * k, 0, TAU); c.stroke(); c.setLineDash([]);
      for (const e of s.ents) {
        if (e.isPlayer || (!e.tagged && !(e.npc && e.npc.engaged))) continue;
        const x = (e.x - cx) * k, y = (e.y - cy) * k;
        if (Math.abs(x) > S / 2 || Math.abs(y) > S / 2) continue;
        if (!e.alive) {
          if (e.role === 'target') { c.strokeStyle = '#cbd5e1'; c.lineWidth = 1.5; c.beginPath(); c.moveTo(x - 3, y - 3); c.lineTo(x + 3, y + 3); c.moveTo(x + 3, y - 3); c.lineTo(x - 3, y + 3); c.stroke(); }
          continue;
        }
        if (e.role === 'target') diamond(c, x, y, 4, '#ef4444');
        else { c.fillStyle = e.role === 'civ' ? '#e5e7eb' : e.npc.engaged ? '#f43f5e' : '#fb923c'; c.beginPath(); c.arc(x, y, 2.4, 0, TAU); c.fill(); }
      }
      if (M.car && !M.car.dead) {
        const x = (M.car.x - cx) * k, y = (M.car.y - cy) * k;
        if (Math.abs(x) < S / 2 && Math.abs(y) < S / 2) { c.fillStyle = M.car.driver ? '#60a5fa' : '#bfdbfe'; rr(c, x - 3, y - 2, 6, 4, 1); c.fill(); }
      }
    }

    // ====================================================================
    // Input
    // ====================================================================
    function toUI(x, y) {
      const sw = api.stage.clientWidth, sh = api.stage.clientHeight, U = uiScale();
      return { x: ((x / api.W) * sw) / U, y: ((y / api.H) * sh) / U, cssX: (x / api.W) * sw };
    }
    const inCircle = (pt, b) => b && Math.hypot(pt.x - b.x, pt.y - b.y) < b.r + 6;
    const inRect = (pt, b) => b && pt.x > b.x && pt.x < b.x + b.w && pt.y > b.y && pt.y < b.y + b.h;
    function hitButtons(pt) {
      if (buildingViewBusy()) return 'ui';
      carryHudSync();
      const L = s.layout;
      const p = s.ents[0];
      if(efSupportClick(pt))return 'ui';
      if(efFacilityClick(pt))return 'ui';
      if(railTravelClick(pt))return 'ui';
      if (s.mapOpen) { if (hhInside()) { tacticalMapOpen(false); return 'ui'; } mlCancel(); const tactical = tacticalMapUI(); if (tactical) { tactical.click(pt); return 'ui'; } if(efMapClick(pt))return 'ui';tacticalMapOpen(false); return 'ui'; }
      if (inCircle(pt, L.pause)) { carrySetMenu(false); api.pause(); return 'ui'; }
      if (inCircle(pt, L.full)) { carrySetMenu(false); if (full) exitFull(); else enterFull(); return 'ui'; }
      if (inCircle(pt, L.map) || inRect(pt, L.mini)) { tacticalMapOpen(true); return 'ui'; }
      if (inCircle(pt,L.hudInfo)) { carrySetMenu(false);s.hudExpanded=!s.hudExpanded;return 'ui'; }
      if (p.alive && inRect(pt,L.weaponToggle)) { carrySetMenu(!s.weaponMenuOpen);return 'ui'; }
      if (s.weaponMenuOpen) {
        if(inRect(pt,L.eqScope)){eqCycleScope(p);return 'ui';}
        if(inRect(pt,L.eqShield)){eqToggleShield(p);return 'ui';}
        if(L.slots)for(let i=0;i<L.slots.length;i++)if(inRect(pt,L.slots[i])){switchTo(i);requestLock();return 'ui';}
        if(inRect(pt,L.weaponPanel))return 'ui';
        // Closing the picker consumes the tap so it cannot also fire a weapon.
        carrySetMenu(false);return 'ui';
      }
      if (hhInside() && p.alive) for (const [key,direction] of [['futurePrevious',-1],['futureNext',1],['futureExit',0]]) {
        if (inRect(pt,L[key])) { if (L[key].enabled) hhFutureNavigate(direction); return 'ui'; }
      }
      if(!hhInside()&&p.alive&&L.piAction&&Math.hypot(pt.x-L.piAction.x,pt.y-L.piAction.y)<L.piAction.r){piInteract();return 'ui';}
      if(!hhInside()&&p.alive)for(const name of ['dwDown','dwDisarm']){const b=L[name];if(b&&Math.hypot(pt.x-b.x,pt.y-b.y)<(b.r||21)){if(name==='dwDisarm')dwTrapInteract();else dwTransfer(dwPortal());return 'ui';}}
      if(!hhInside()&&p.alive)for(const name of ['pentaUp','pentaDown','pentaAction']){const b=L[name];if(b&&Math.abs(pt.x-b.x)<=b.w/2&&Math.abs(pt.y-b.y)<=b.h/2){if(name==='pentaAction')pentaInteract();else pentaTransfer(p,name==='pentaUp'?1:-1);return 'ui';}}
      if (p.alive && s.mode !== 'assassin' && inRect(pt, L.eqScope)) { eqCycleScope(p); return 'ui'; }
      if (p.alive && s.mode !== 'assassin' && inRect(pt, L.eqShield)) { eqToggleShield(p); return 'ui'; }
      if(vehicleScopeMount()){
        if(inCircle(pt,L.ads)){toggleVehicleScope();return 'ui';}
        if(inCircle(pt,L.vehicleZoom)){cycleVehicleScope();return 'ui';}
      }
      if (!touchMode) return null;
      if(inCircle(pt,L.efFacility)&&efFacilityNear()){efFacilityInteract();return 'ui';}
      if(vehicleFreeAim(p.vehicle)&&inCircle(pt,L.freeLook))return 'freeLook';
      if (mlrsGuidedCurrent() && inCircle(pt,L.missile)) { mlrsGuidedFire(); return 'ui'; }
      if (aircraftCurrent() && inCircle(pt, L.missile)) { aircraftFireMissile(); return 'ui'; }
      if (s.mode === 'open' && p.craft) {
        if (inCircle(pt, L.exit)) { exitCraft(); return 'ui'; }
        if (inCircle(pt, L.action)) { if(!nfDeckInteract())boardCraft(nearCraft(p)); return 'ui'; }
        if (inCircle(pt, L.fire) || inCircle(pt, L.fire2)) return 'fire';
        if (inCircle(pt, L.bomb)) { warBomb(); return 'ui'; }
        if (inCircle(pt, L.torp)) { warTorpedo(); return 'ui'; }
        if (inCircle(pt, L.ads)) { s.input.adsToggle = !s.input.adsToggle; return 'ui'; }
        return null;
      }
      if (s.mode === 'assassin') {
        if (inCircle(pt, L.fire) || inCircle(pt, L.fire2)) return 'fire';
        if (inCircle(pt, L.ads)) { s.input.adsToggle = !s.input.adsToggle; return 'ui'; }
        if (inCircle(pt, L.zoom)) { cycleZoom(1, true); return 'ui'; }
        if (inCircle(pt, L.reload)) { startReload(p); return 'ui'; }
        if (inCircle(pt, L.crouch)) { toggleCrouch(); return 'ui'; }
        return null;
      }
      if (mlActive(p)) {
        if(mlFocusActive(p)&&inCircle(pt,L.meleeFocus)){mlFocusToggle();return 'ui';}
        if(mlFocusActive(p)&&inCircle(pt,L.meleeCycle)){mlFocusCycle();return 'ui';}
        const side = mlRuntime.hitControl(L, pt);
        if (side) return 'melee-' + side;
      }
      if (inCircle(pt,L.carrierLift)) { ncCarrierVehicleInteract(); return 'ui'; }
      if (inCircle(pt, L.action)) { mlCancel(); if(p.vehicle||efFacilityNear()?.mobile&&!efFacilityPickupReady())toggleVehicle();else interact(); return 'ui'; }
      if (inCircle(pt, L.heliUp)) return 'heliUp';
      if (inCircle(pt, L.heliDown)) return 'heliDown';
      if (!mlActive(p) && (inCircle(pt, L.fire) || inCircle(pt, L.fire2))) return 'fire';
      if (!mlActive(p) && inCircle(pt, L.nade)) return 'nade';
      if (!mlActive(p) && inCircle(pt, L.ads)) { s.input.adsToggle = !s.input.adsToggle; return 'ui'; }
      if (!mlActive(p) && inCircle(pt, L.reload)) { startReload(p); return 'ui'; }
      if (inCircle(pt, L.heal)) { useMed(p); return 'ui'; }
      if (inCircle(pt, L.crouch)) { toggleCrouch(); return 'ui'; }
      if (inCircle(pt, L.jump)) { playerJump(); return 'ui'; }
      if (inCircle(pt, L.roll)) { playerRoll(); return 'ui'; }
      return null;
    }
    // jump / roll toward where you're steering (or where you look when standing still)
    function playerJump() {
      const p = s.ents[0];
      if (!p.alive || api.state !== 'playing' || s.mode === 'assassin' || p.craft || p.mortar || p.railPassenger) return;
      const yaw=playerViewYaw(),d = s.moveDir || { x: Math.cos(yaw), y: Math.sin(yaw) };
      if (doJump(p, d.x, d.y) && p.air) api.tone(260, 0.05, 'triangle', 0.04, 1.3);
    }
    function playerRoll() {
      const p = s.ents[0];
      if (!p.alive || api.state !== 'playing' || mlActive(p) || s.mode === 'assassin' || p.craft || p.mortar || p.railPassenger) return;
      const d = s.moveDir || { x: Math.cos(s.yaw), y: Math.sin(s.yaw) };
      if (!equipmentShieldRaised(p)) doRoll(p, d.x, d.y);
    }
    function startNadeAim() {
      if(hhLive()&&hhRuntime.blocksCombat?.())return false;
      const p = s.ents[0];
      if (p.grenades <= 0 || p.vehicle || p.mortar || p.railPassenger || p.alt > 0 || !p.alive) { if (p.grenades <= 0) say('수류탄이 없어요', '#fca5a5'); return false; }
      if (equipmentShieldRaised(p)) { say('방패를 수납한 뒤 수류탄을 사용하세요', '#cbd5e1'); return false; }
      s.aimNade = { t: 0 };
      s.input.adsToggle = false;
      return true;
    }
    function releaseNade() {
      if (!s.aimNade) return;
      s.aimNade = null;
      const p = s.ents[0];
      if (!p.alive || p.vehicle) return;
      const v = grenadeVelocity(s.yaw, s.pitch);
      p.aim = s.yaw;
      throwGrenade(p, v.vx, v.vy, v.vh);
    }
    const canvasEl = api.canvas;
    document.addEventListener('pointerlockchange', () => {
      if (!s) return;
      s.input.locked = document.pointerLockElement === canvasEl;
      if(!s.input.locked&&railUnlockPending){railUnlockPending=false;return;}
      if (!s.input.locked && menuUnlockPending) { menuUnlockPending = false; return; }
      if (!s.input.locked && api.state === 'playing' && !touchMode && !s.mapOpen) { s.input.fire = false; s.input.ads = false; api.pause(); }
    });
    document.addEventListener('pointerlockerror', () => { if (s) s.input.noLock = true; });
    // Arcade handles Escape before game.keyDown. While the railway menu owns
    // input, capture it here so Escape closes the menu without pausing play.
    document.addEventListener('keydown', event => {
      if(!railTravelBusy()||api.state!=='playing'||!battleVisible()||event.ctrlKey||event.metaKey||event.altKey||/^(INPUT|SELECT|TEXTAREA)$/.test(event.target?.tagName||''))return;
      event.preventDefault();event.stopImmediatePropagation();
      const key=event.key.toLowerCase();
      if(!event.repeat||key.startsWith('arrow'))railTravelKey(key);
    },true);
    // Facility menus capture Escape before the arcade pause handler.
    document.addEventListener('keydown',event=>{
      if(!efFacilityBusy()||api.state!=='playing'||!battleVisible()||event.ctrlKey||event.metaKey||event.altKey||/^(INPUT|SELECT|TEXTAREA)$/.test(event.target?.tagName||''))return;
      event.preventDefault();event.stopImmediatePropagation();if(!event.repeat)efFacilityKey(event.key.toLowerCase());
    },true);
