      const restart = api.panels.pause.querySelector('.ov-ghost');
      if (restart) {
        const same = !s || s.mode === mode;
        restart.textContent = mode === 'open' ? (same ? '새 대륙 (처음부터)' : '오픈월드 이어하기') : !same ? (mode === 'assassin' ? `암살 작전 시작 (임무 ${settings.mission})` : '배틀로얄 시작') : '처음부터';
      }
