    const openWorldMenu = () => settings.mode === 'open' && api.state === 'ready';
    function preview() {
      if (api.state !== 'ready' && s) return;
      if (settings.mode === 'open') return;
      reset();
      if (s.mode === 'royale') { for (const e of s.ents) e.alt = 0; s.zone.timer = 999; }
    }
    buildModeBox(api.panels.start);
    buildModeBox(api.panels.over);
    buildModeBox(api.panels.pause);
    syncModes();
    // ====================================================================
    // 저장 슬롯: 저장 1–5 and an automatic slot (written whenever the game pauses — leaving the page,
    // switching tabs or pressing pause). Local writes stay synchronous; the cloud
