          if (AUTO_NAMES[k] && kind === 'load' && !fits(m)) continue;
          shown++;
          const row = document.createElement('div');
          row.className = 'ov-slot-row';
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'ov-slot' + (m ? '' : ' empty') + (B.confirm === k ? ' confirm' : '');
          const name = document.createElement('b'); name.textContent = slotName(k);
          const info = document.createElement('span');
